import{_ as o,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"RBD for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"RBD for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["RBD","会议纪要","分布式存储","性能优化","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/RBD_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/RBD_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/RBD_for_Ceph_Developer_Summit_-_Vampire.md"};function n(s,r,l,d,p,m){return a(),e("div",null,[...r[0]||(r[0]=[t('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议是 Ceph Developer Summit（CDS）Vampire 版本的 RBD 专题讨论，由 Ilya 主持，聚焦于 RBD mirroring、lib rbd、CLI 工具以及内核客户端等方向的开发计划。Vampire 版本计划于明年春季早期发布，代码冻结预计在一月初，因此是一个较短的发布周期。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="一、rbd-mirroring-全动态-group-支持" tabindex="-1">一、RBD Mirroring：全动态 Group 支持 <a class="header-anchor" href="#一、rbd-mirroring-全动态-group-支持" aria-label="Permalink to &quot;一、RBD Mirroring：全动态 Group 支持&quot;">​</a></h3><p><strong>当前状态</strong></p><p>基于 snapshot 的 consistency group mirroring 代码目前仍在 integration branch，尚未合并到主线。Umbrella 版本实现了&quot;半动态 group&quot;支持，即允许在 mirroring 开启状态下向 group 中添加 image。</p><p><strong>Vampire 版本目标：完整动态 group 支持</strong></p><p>核心工作是支持在 mirroring 开启时从 group 中移除 image。当前的主要障碍是 group snapshot 的语义过于复杂。</p><p><strong>当前 group snapshot 的语义问题</strong></p><p>现有实现允许从 group 中移除 image，但该操作只影响 group 的&quot;头部&quot;（head revision），而已有的 group snapshots 仍会继续引用被移除的 image，形成所谓的&quot;extended membership&quot;概念。这种设计：</p><ul><li>语义复杂，难以理解，文档中从未清晰说明</li><li>给 mirroring 的跨集群状态同步带来极大复杂性</li><li>容易导致不必要的全量 resync，破坏用户的 RTO/RPO 目标</li></ul><p><strong>Prasanna 提出的语义变更方案</strong></p><p>提议修改 <code>rbd group image rm</code> 的默认行为：</p><ul><li><strong>新默认行为</strong>：若 image 被一个或多个 group snapshot 引用，返回 <code>EBUSY</code> 错误，阻止移除</li><li><strong><code>--force</code> 选项</strong>：保留原有行为，强制移除（不检查 snapshot 依赖）</li><li><strong><code>--purge-user-group-snapshots</code> 选项</strong>：先自动清理所有引用该 image 的 group snapshots，再执行移除</li></ul><p>此变更属于<strong>非向后兼容变更</strong>，但经调查 OpenStack 已不再使用 RBD groups（已在更高层面实现 grouping 语义），因此影响范围有限。</p><p><strong>mirroring 约束</strong></p><p>对于存在 extended membership 的 group，不允许开启 mirroring。</p><h3 id="二、rbd-fuzzer-随机测试工具" tabindex="-1">二、RBD Fuzzer（随机测试工具） <a class="header-anchor" href="#二、rbd-fuzzer-随机测试工具" aria-label="Permalink to &quot;二、RBD Fuzzer（随机测试工具）&quot;">​</a></h3><ul><li>VNA 已实现独立脚本原型，已发现 group snapshot unlinking 代码中的一个 bug（附有修复 PR）</li><li>当前优先级：集成到 Jenkins CI 流水线</li><li>后续目标：作为 Teuthology task 运行，覆盖 standalone image mirroring 和 group mirroring（仅限 snapshot-based，不涉及 journal-based）</li><li>类似于 mon thrasher、OSD thrasher 等现有工具</li></ul><h3 id="三、mirror-snapshot-修剪-pruning-问题" tabindex="-1">三、Mirror Snapshot 修剪（Pruning）问题 <a class="header-anchor" href="#三、mirror-snapshot-修剪-pruning-问题" aria-label="Permalink to &quot;三、Mirror Snapshot 修剪（Pruning）问题&quot;">​</a></h3><p><strong>问题描述</strong></p><p>在 failover/failback 场景中，primary demote 产生的 non-primary demote snapshots 在 failback 之前一直残留，可能消耗大量空间，极端情况下可达集群容量的 50%。</p><p><strong>修复进展</strong></p><ul><li>Standalone image 的修复已在 Umbrella 版本完成，backport 正在推进</li><li>Group mirroring 的对应修复由 Mickey 负责，PR 已就绪，将在 Vampire 版本合并</li></ul><h3 id="四、多-rbd-mirror-daemon-支持" tabindex="-1">四、多 RBD Mirror Daemon 支持 <a class="header-anchor" href="#四、多-rbd-mirror-daemon-支持" aria-label="Permalink to &quot;四、多 RBD Mirror Daemon 支持&quot;">​</a></h3><p><strong>现状问题</strong></p><ul><li>现有多 daemon 支持代码未经充分测试</li><li>group mirroring 对 image map 的复用方式过于粗糙，在 semi-dynamic 和 fully dynamic groups 下不可持续</li><li>计划由 Ramina 重新设计相关代码，停止滥用 image map 接口</li></ul><p><strong>Kubernetes 自动扩缩容</strong></p><p>RBD mirror daemon 无本地状态，理论上可透明地在 Kubernetes 中自动扩缩容。当前缺少用于触发自动扩缩容的监控指标。</p><p>规划中的新状态指标：<strong>waiting to sync</strong>，用于反映因并发 sync 数量限制导致的排队情况。当前默认并发 sync 数为 5（该值最初为经验估计）。该指标有助于：</p><ul><li>判断是否需要调整并发 sync 上限</li><li>判断是否需要增加 RBD mirror daemon 实例</li></ul><h3 id="五、sync-正确性问题" tabindex="-1">五、Sync 正确性问题 <a class="header-anchor" href="#五、sync-正确性问题" aria-label="Permalink to &quot;五、Sync 正确性问题&quot;">​</a></h3><p>以下两个问题已在多个版本的 backlog 中存在，Vampire 版本将尝试至少解决其中之一：</p><ol><li><strong>Discard 未正确传播</strong>：较容易修复</li><li><strong>Clone 相关的 copy-up 操作同步异常</strong>：较复杂，涉及虚拟化场景中 golden image + clone VM 的镜像链，同时存在 Ceph-CSI 侧的阻塞问题</li></ol><h3 id="六、n-1-行为修复-standalone-image-rollback" tabindex="-1">六、N-1 行为修复（Standalone Image Rollback） <a class="header-anchor" href="#六、n-1-行为修复-standalone-image-rollback" aria-label="Permalink to &quot;六、N-1 行为修复（Standalone Image Rollback）&quot;">​</a></h3><p>会议中提到该问题虽未列入主议程，但与 force promote 有一定关联。决定在 Vampire 版本中单独推进该修复，不依赖 force promote。</p><h2 id="lib-rbd-与-cli" tabindex="-1">lib rbd 与 CLI <a class="header-anchor" href="#lib-rbd-与-cli" aria-label="Permalink to &quot;lib rbd 与 CLI&quot;">​</a></h2><h3 id="rbddu-改进" tabindex="-1">rbddu 改进 <a class="header-anchor" href="#rbddu-改进" aria-label="Permalink to &quot;rbddu 改进&quot;">​</a></h3><ol><li><strong>显示非用户 snapshot 的空间占用</strong>：包括 trash、group、mirror snapshots，PR 已就绪，预计数周内合并</li><li><strong>slow mode（<code>--exact</code>）精确化</strong>：修复当前 slow mode 实际上也不精确的问题，优化查询逻辑，牺牲少量性能换取准确结果</li><li><strong><code>rbd diff</code> 命令支持非用户 snapshot</strong>：将从大 PR 中拆分为独立 PR，预计在 Vampire 版本合并</li></ol><h3 id="rbd-export-import-非用户-snapshot-支持" tabindex="-1">RBD export/import 非用户 snapshot 支持 <a class="header-anchor" href="#rbd-export-import-非用户-snapshot-支持" aria-label="Permalink to &quot;RBD export/import 非用户 snapshot 支持&quot;">​</a></h3><p>需要引入新的 export format 版本（V3），以支持 snapshot namespace 信息。相关语义问题待讨论（如 mirror snapshot、group snapshot 的导入导出是否有意义）。该改动体量较大，可能不会推进。</p><h3 id="移除-pm-persistent-memory-模式的-pwl-cache" tabindex="-1">移除 PM（Persistent Memory）模式的 PWL Cache <a class="header-anchor" href="#移除-pm-persistent-memory-模式的-pwl-cache" aria-label="Permalink to &quot;移除 PM（Persistent Memory）模式的 PWL Cache&quot;">​</a></h3><ul><li>PM/RWL 模式将从代码库中<strong>物理删除</strong></li><li>原因：Intel 已停止 Optane PM 硬件供货，无已知用户，现有实现依赖的 PMDK 库有变更导致代码已损坏，且只能用文件模拟测试</li><li><strong>保留</strong>：SSD 模式的 PWL cache 和内存缓存不受影响</li></ul><h3 id="时间戳一致性" tabindex="-1">时间戳一致性 <a class="header-anchor" href="#时间戳一致性" aria-label="Permalink to &quot;时间戳一致性&quot;">​</a></h3><p>当前 CLI（如 <code>rbd snap ls</code>）使用本地时区，而 mirror snapshot scheduler 等已切换为 UTC，存在不一致。计划统一为 UTC，实现本身不复杂，需决策后推进。</p><h2 id="内核客户端" tabindex="-1">内核客户端 <a class="header-anchor" href="#内核客户端" aria-label="Permalink to &quot;内核客户端&quot;">​</a></h2><ol><li><strong>exclusion lock watch 丢失问题</strong>：高 Q depth + 高 OSD op latency 场景下可能触发 blocklist，在 OpenShift Virtualization / KubeVirt 环境中已重现，需内核驱动侧修复，为第一优先级</li><li><strong>upmap rebalancer 支持</strong>：仍在 backlog，接近完成但被推迟</li><li><strong>CRUSH multi-step retry（MSR）rules 支持</strong>：针对特定 EC profile，仍在 backlog</li><li><strong>EC direct reads</strong>：已在 Umbrella 版本的 RADOS 层实现，计划移植到内核客户端</li></ol><p><strong>EC direct reads 说明</strong>：传统 EC 读流程需经过&quot;伪主 OSD&quot;中转，该 OSD 需协调其他 OSD 读取 shard 并聚合返回，负载集中。Direct reads 允许客户端直接与持有目标 shard 的 OSD 通信，减少不必要的跳转，对所有启用 fast EC 的 pool 均有性能提升。</p><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ul><li>Vampire 版本将修改 <code>rbd group image rm</code> 默认语义，从宽松移除改为严格保护（返回 EBUSY），通过 <code>--force</code> 和 <code>--purge-user-group-snapshots</code> 保持向后兼容</li><li>PM/RWL cache 模式将在 Vampire 版本中从代码库删除</li><li>snapshot-based group mirroring 上游合并目标推迟至 Vampire 之后版本</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>任务</th></tr></thead><tbody><tr><td>Prasanna</td><td><code>rbd group image rm</code> 语义变更 PR，targeting main branch</td></tr><tr><td>Mickey</td><td>Group mirroring mirror snapshot 修剪修复 PR 合并</td></tr><tr><td>Mickey</td><td>新增 image/group replay 状态（waiting to sync）</td></tr><tr><td>Ramina</td><td>多 RBD mirror daemon 下 group 支持重构</td></tr><tr><td>VNA</td><td>Fuzzer 集成进 Jenkins，后续扩展为 Teuthology task</td></tr><tr><td>RBD 团队</td><td>rbddu non-user snapshot 显示 PR 合并</td></tr><tr><td>RBD 团队</td><td>rbddu slow mode 精确化修复</td></tr><tr><td>RBD 团队</td><td><code>rbd diff</code> 支持非用户 snapshot，拆分为独立 PR</td></tr><tr><td>Kifu/RBD 团队</td><td>移除 PWL cache PM 模式代码</td></tr><tr><td>RBD 团队</td><td>确认 timestamp 一致性方案并推进</td></tr><tr><td>内核团队</td><td>exclusion lock watch 丢失 bug 修复（最高优先级）</td></tr><tr><td>内核团队</td><td>EC direct reads 移植至内核客户端</td></tr></tbody></table>',52)])])}const g=o(i,[["render",n]]);export{u as __pageData,g as default};
